// Stateless cart API: no session data kept in process memory.
const express = require("express");
const crypto = require("crypto");
const os = require("os");
const { createClient } = require("redis");

const PORT = process.env.PORT || 3000;
const REDIS_URL = process.env.REDIS_URL || "redis://localhost:6379";
const INSTANCE = process.env.INSTANCE_ID || os.hostname(); // shows which replica answered
const SESSION_TTL = 1800; // seconds; idle sessions expire in Redis

const redis = createClient({ url: REDIS_URL }); // externalised session store
redis.on("error", (e) => console.error("redis error:", e.message));

const app = express();

// Read the session id from the cookie (32 hex chars), or return null.
function getSid(req) {
  const m = /(?:^|;\s*)sid=([a-f0-9]{32})/.exec(req.headers.cookie || "");
  return m ? m[1] : null;
}

// Health check used by nginx and the ALB target group.
// It fails if Redis is unreachable, so a broken instance gets no traffic.
app.get("/healthz", async (req, res) => {
  try { await redis.ping(); res.send("ok"); }
  catch { res.status(503).send("redis down"); }
});

// Per-user data: stored in Redis, so ANY replica can serve the next request.
app.get("/api/cart/add", async (req, res) => {
  let sid = getSid(req);
  if (!sid) {
    sid = crypto.randomBytes(16).toString("hex");
    res.setHeader("Set-Cookie", `sid=${sid}; HttpOnly; Path=/; SameSite=Lax; Max-Age=${SESSION_TTL}`);
  }
  const key = `sess:${sid}`;
  const item = String(req.query.item || "book").slice(0, 40);
  await redis.hIncrBy(key, item, 1);       // atomic update, safe across replicas
  await redis.expire(key, SESSION_TTL);    // sliding expiry
  res.setHeader("Cache-Control", "private, no-store"); // CDN must never cache this
  res.json({ servedBy: INSTANCE, cart: await redis.hGetAll(key) });
});

// Same for every user: safe to cache at the edge.
app.get("/api/products", (req, res) => {
  res.setHeader("Cache-Control", "public, max-age=60, s-maxage=300"); // s-maxage = shared/CDN TTL
  res.json({ servedBy: INSTANCE, generatedAt: new Date().toISOString(),
    products: [{ id: 1, name: "book" }, { id: 2, name: "pen" }] });
});

redis.connect().then(() => {
  app.listen(PORT, () => console.log(`${INSTANCE} listening on ${PORT}`));
});

{
  "name": "multi-az-web-tier",
  "version": "1.0.0",
  "description": "Stateless cart API with sessions in Redis",
  "main": "server.js",
  "private": true,
  "scripts": {
    "start": "node server.js"
  },
  "engines": {
    "node": ">=20"
