# L7 load balancer + edge-style cache (local stand-in for ALB + CloudFront).
events {}

http {
  # Shared cache zone: 10 MB of keys, up to 100 MB of cached bodies.
  proxy_cache_path /tmp/edge keys_zone=edge:10m max_size=100m inactive=10m;

  upstream web {
    least_conn;                     # pick the replica with the fewest active connections
    # (remove least_conn to get the default: round robin)
    server app1:3000 max_fails=2 fail_timeout=5s;  # passive health check
    server app2:3000 max_fails=2 fail_timeout=5s;
    # hash $cookie_sid consistent;  # affinity via consistent hashing - we do NOT need it
  }

  server {
    listen 80;

    # Public, cacheable content.
    location /api/products {
      proxy_pass http://web;
      proxy_cache edge;
      proxy_cache_key "$scheme$host$uri";       # cache key ignores cookies and query string
      proxy_cache_valid 200 60s;                # fallback TTL; upstream s-maxage wins
      proxy_cache_use_stale error timeout updating; # serve stale if origins fail
      add_header X-Cache-Status $upstream_cache_status always; # MISS / HIT / STALE
    }

    # Everything else, including the per-user cart: never cached.
    location / {
      proxy_pass http://web;
      proxy_next_upstream error timeout http_502 http_503; # retry on the other replica
      proxy_set_header Host $host;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
  }
}

