import json, random, time, redis
r = redis.Redis(host="localhost", port=6379, decode_responses=True)
BASE_TTL = 300  # seconds

def ttl():
    return BASE_TTL + random.randint(-30, 30)  # jitter vs stampede

def get_product(pid, db):
    key = f"product:{pid}"
    cached = r.get(key)
    if cached is not None:
        return None if cached == "__NULL__" else json.loads(cached)
    # single-flight lock: only one request rebuilds the key
    if r.set(f"lock:{key}", 1, nx=True, ex=10):
        try:
            row = db.fetch_product(pid)  # SELECT ... WHERE id=%s
            if row is None:
                r.set(key, "__NULL__", ex=60)  # negative cache vs penetration
            else:
                r.set(key, json.dumps(row), ex=ttl())
            return row
        finally:
            r.delete(f"lock:{key}")
    time.sleep(0.05)  # another worker is loading; retry
    return get_product(pid, db)

def update_product(pid, fields, db):
    db.update_product(pid, fields)  # 1. write DB (source of truth)
    r.delete(f"product:{pid}")      # 2. invalidate, don't update

# Stale-data risks: (1) TTL window if invalidation is missed,
# (2) reader caches old row between DB write and delete (race),
# (3) miss repopulated from a lagging read replica.

