{
  "name": "product-cache-aside",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Cache-aside product page with stampede, penetration and hot-key protection",
  "scripts": {
    "start": "node src/server.js"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "express": "^4.21.2",
    "pg": "^8.13.1",
    "redis": "^4.7.0"
  }
}

// Source of truth. Deliberately slow, so cache hits vs misses are easy to see.
import pg from 'pg';

export const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL || 'postgres://shop:shop@localhost:5432/shop',
});

export const stats = { dbReads: 0 }; // counts real DB loads (stampede test)

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function findProduct(id) {
  stats.dbReads++;
  await sleep(100); // simulate an expensive query or join
  const { rows } = await pool.query(
    'SELECT id, name, price_inr, stock, updated_at FROM products WHERE id = $1',
    [id]
  );
  return rows[0] ?? null; // null = product does not exist
}

export async function updatePrice(id, priceInr) {
  const { rowCount } = await pool.query(
    'UPDATE products SET price_inr = $2, updated_at = now() WHERE id = $1',
    [id, priceInr]
  );
  return rowCount > 0;
}

// Cache-aside helper: the APP (not the cache) loads from the DB on a miss.
import { createClient } from 'redis';

export const redis = createClient({ url: process.env.REDIS_URL || 'redis://localhost:6379' });
redis.on('error', (e) => console.error('redis error:', e.message));
await redis.connect();

const NULL_MARKER = '__NULL__'; // negative cache value (penetration fix)
const NULL_TTL_SEC = 30;        // keep it short so newly created items appear quickly
const L1_MS = 1000;             // tiny in-process cache for hot keys
const l1 = new Map();           // key -> { value, expires }

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// TTL jitter: spread expiry so many keys do not expire together (avoids a stampede at one time)
const withJitter = (ttl) => ttl + Math.floor(Math.random() * ttl * 0.1);

export async function getOrLoad(key, loader, ttlSec = 300) {
  // 1. Hot key fix: serve from local memory, so one Redis shard is not hammered
  const local = l1.get(key);
  if (local && local.expires > Date.now()) return local.value;

  for (let attempt = 0; attempt < 20; attempt++) {
    // 2. Try the cache
    const cached = await redis.get(key);
    if (cached !== null) {
      const value = cached === NULL_MARKER ? null : JSON.parse(cached);
      l1.set(key, { value, expires: Date.now() + L1_MS });
      return value;
    }
    // 3. Stampede fix: only ONE caller rebuilds the key (SET NX with expiry = simple lock)
    const gotLock = await redis.set(`lock:${key}`, '1', { NX: true, PX: 3000 });
    if (gotLock) {
      try {
        const value = await loader(); // miss: read the DB
        if (value === null) {
          await redis.set(key, NULL_MARKER, { EX: NULL_TTL_SEC });
        } else {
          await redis.set(key, JSON.stringify(value), { EX: withJitter(ttlSec) });
        }
        return value;
      } finally {
        await redis.del(`lock:${key}`);
      }
    }
    await sleep(50); // others wait briefly, then re-check the cache
  }
  return loader(); // lock holder too slow: fall back to the DB
}

// Called after a DB write. Delete the key; do not update it in place.
export async function invalidate(key) {
  l1.delete(key); // clears only THIS instance's L1; other instances keep theirs up to L1_MS
  await redis.del(key);
}

// Product page API using cache-aside reads and delete-on-write invalidation.
import express from 'express';
import { findProduct, updatePrice, stats } from './db.js';
import { getOrLoad, invalidate } from './cache.js';

const app = express();
app.use(express.json());
const PORT = Number(process.env.PORT || 3000);
const TTL_SEC = Number(process.env.CACHE_TTL_SEC || 300);

// Penetration fix, layer 1: reject ids that can never exist before touching cache or DB
function parseId(raw) {
  const id = Number(raw);
  return Number.isInteger(id) && id > 0 && id < 1_000_000 ? id : null;
}

app.get('/products/:id', async (req, res) => {
  const id = parseId(req.params.id);
  if (id === null) return res.status(400).json({ error: 'invalid id' });
  try {
    const product = await getOrLoad(`product:${id}`, () => findProduct(id), TTL_SEC);
    if (!product) return res.status(404).json({ error: 'not found' });
    res.json(product);
  } catch (err) {
    // If Redis is down, degrade to the DB instead of failing the page
    console.error(err.message);
    const product = await findProduct(id);
    if (!product) return res.status(404).json({ error: 'not found' });
    res.json(product);
  }
});

app.put('/products/:id', async (req, res) => {
  const id = parseId(req.params.id);
  const price = Number(req.body?.price_inr);
  if (id === null || !Number.isInteger(price) || price <= 0) {
    return res.status(400).json({ error: 'invalid input' });
  }
  const ok = await updatePrice(id, price); // 1. write the source of truth first
  if (!ok) return res.status(404).json({ error: 'not found' });
  await invalidate(`product:${id}`);       // 2. then delete the cache entry
  res.json({ updated: id, price_inr: price });
});

// Shows how many real DB reads happened. 50 parallel misses should give about 1.
app.get('/stats', (_req, res) => res.json(stats));

app.listen(PORT, () => console.log(`product page on http://localhost:${PORT}`));

