import { randomBytes } from 'node:crypto';

// UUIDv7 (RFC 9562): 48-bit Unix time in ms + version + variant + random bits.
// Sorts by creation time, so B-tree index inserts stay near the end of the index.
export function uuidv7() {
  const b = randomBytes(16);
  const ms = BigInt(Date.now());
  for (let i = 0; i < 6; i++) {
    b[i] = Number((ms >> BigInt(8 * (5 - i))) & 0xffn); // big-endian timestamp
  }
  b[6] = (b[6] & 0x0f) | 0x70; // version 7
  b[8] = (b[8] & 0x3f) | 0x80; // variant 10xx
  const h = b.toString('hex');
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

// Snowflake-style 64-bit ID: 41 bits time | 10 bits worker | 12 bits sequence.
// No coordination needed between servers, as long as each has a unique WORKER_ID.
const EPOCH = 1704067200000n; // custom epoch: 2024-01-01T00:00:00Z
const WORKER_ID = BigInt(process.env.WORKER_ID ?? 1) & 1023n;
let lastMs = -1n;
let seq = 0n;

export function snowflake() {
  let now = BigInt(Date.now());
  if (now < lastMs) throw new Error('Clock moved backwards; refusing to create duplicate IDs');
  if (now === lastMs) {
    seq = (seq + 1n) & 4095n; // up to 4096 IDs per ms per worker
    if (seq === 0n) {
      while (now <= lastMs) now = BigInt(Date.now()); // wait for the next millisecond
    }
  } else {
    seq = 0n;
  }
  lastMs = now;
  return (((now - EPOCH) << 22n) | (WORKER_ID << 12n) | seq).toString();
}

import express from 'express';
import pg from 'pg';
import { createHash } from 'node:crypto';
import { uuidv7, snowflake } from './ids.js';

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL ?? 'postgres://pay:pay@localhost:5432/payments',
});
const app = express();
app.use(express.json());

app.post('/payments', async (req, res) => {
  const key = req.get('Idempotency-Key'); // client creates it once, reuses it on every retry
  if (!key || key.length > 255) return res.status(400).json({ error: 'Idempotency-Key header required' });
  const { customerId, amountPaise, currency = 'INR' } = req.body ?? {};
  if (!customerId || !Number.isInteger(amountPaise) || amountPaise <= 0) {
    return res.status(400).json({ error: 'customerId and positive integer amountPaise required' });
  }
  const requestHash = createHash('sha256')
    .update(JSON.stringify({ customerId, amountPaise, currency })).digest('hex');

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Claim the key. A concurrent insert of the same key WAITS here until the first transaction ends.
    const claim = await client.query(
      'INSERT INTO idempotency_keys (idem_key, request_hash) VALUES ($1, $2) ON CONFLICT (idem_key) DO NOTHING RETURNING idem_key',
      [key, requestHash]);

    if (claim.rowCount === 1) {
      // First time we see this key: charge, then save the response, all in ONE transaction.
      const id = snowflake();
      const publicId = uuidv7();
      await client.query(
        'INSERT INTO payments (id, public_id, idem_key, customer_id, amount_paise, currency) VALUES ($1, $2, $3, $4, $5, $6)',
        [id, publicId, key, customerId, amountPaise, currency]);
      const body = { paymentId: publicId, status: 'succeeded', customerId, amountPaise, currency };
      await client.query('UPDATE idempotency_keys SET response_code = 201, response_body = $2 WHERE idem_key = $1', [key, body]);
      await client.query('COMMIT'); // charge and key become visible together, or not at all
      return res.status(201).json(body);
    }

    // Key already used: never charge again, replay the saved answer.
    await client.query('ROLLBACK');
    const { rows } = await pool.query(
      'SELECT request_hash, response_code, response_body FROM idempotency_keys WHERE idem_key = $1', [key]);
    const saved = rows[0];
    if (!saved || saved.response_code === null) return res.status(409).json({ error: 'Request in progress, retry later' });
    if (saved.request_hash !== requestHash) {
      return res.status(422).json({ error: 'Idempotency-Key reused with a different request body' });
    }
    res.set('Idempotent-Replayed', 'true');
    return res.status(saved.response_code).json(saved.response_body);
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {}); // failure releases the key, so a retry can succeed
    console.error(err);
    return res.status(500).json({ error: 'Internal error, safe to retry with the same key' });
  } finally {
    client.release();
  }
});

app.get('/customers/:id/payments', async (req, res) => {
  const { rows } = await pool.query(
