import { randomUUID } from 'node:crypto';

// Simulates a flaky network: the client retries the SAME payment many times.
const BASE = process.env.API_URL ?? 'http://localhost:3000';
const customerId = `cust-${Date.now()}`;
const key = randomUUID(); // one key per logical payment, created BEFORE the first attempt
const body = { customerId, amountPaise: 49900, currency: 'INR' }; // Rs 499.00

const pay = (payload, idemKey = key) => fetch(`${BASE}/payments`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json', 'Idempotency-Key': idemKey },
  body: JSON.stringify(payload),
});

// 1) Five retries fired at the same moment (worst case: a double-click plus client retries).
const results = await Promise.all(Array.from({ length: 5 }, () => pay(body)));
for (const r of results) {
  const json = await r.json();
  console.log(r.status, r.headers.get('idempotent-replayed') ?? 'false', json.paymentId);
}

// 2) A late retry after a timeout still gets the original answer.
const late = await pay(body);
console.log('late retry ->', late.status, (await late.json()).paymentId);

// 3) Same key, different amount: rejected, because it is a client bug.
const misuse = await pay({ ...body, amountPaise: 99900 });
console.log('same key, new body ->', misuse.status);

// 4) The proof: exactly one charge exists for this customer.
const summary = await (await fetch(`${BASE}/customers/${customerId}/payments`)).json();
console.log('charges in ledger:', summary);
if (summary.charges !== 1) {
  console.error('FAIL: customer charged more than once');
  process.exit(1);
}
console.log('PASS: 7 requests, 1 charge');

