{
  "name": "distributed-rate-limiter",
  "version": "1.0.0",
  "private": true,
  "description": "Redis token-bucket rate limiter shared by many API servers, with Prometheus SLO alerts",
  "main": "src/server.js",
  "type": "commonjs",
  "engines": { "node": ">=20" },
  "scripts": {
    "start": "node src/server.js"
  },
  "dependencies": {
    "express": "^5.1.0",
    "ioredis": "^5.4.1",
    "prom-client": "^15.1.3"
  }
}

const Redis = require('ioredis');

// Token bucket in Lua: runs atomically inside Redis, so many servers cannot race.
const TOKEN_BUCKET_LUA = `
local key      = KEYS[1]
local capacity = tonumber(ARGV[1])
local refill   = tonumber(ARGV[2])          -- tokens per second
local cost     = tonumber(ARGV[3])
local t        = redis.call('TIME')         -- one shared clock, no app-server skew
local now      = tonumber(t[1]) * 1000 + math.floor(tonumber(t[2]) / 1000)
local data     = redis.call('HMGET', key, 'tokens', 'ts')
local tokens   = tonumber(data[1]) or capacity
local ts       = tonumber(data[2]) or now
tokens = math.min(capacity, tokens + ((now - ts) / 1000) * refill)  -- lazy refill
local allowed = 0
if tokens >= cost then tokens = tokens - cost; allowed = 1 end
redis.call('HSET', key, 'tokens', tokens, 'ts', now)
redis.call('PEXPIRE', key, math.ceil(capacity / refill * 1000) + 1000) -- idle keys expire
return { allowed, tostring(tokens) }
`;

function createRateLimiter({ redisUrl, capacity, refillPerSec, timeoutMs }) {
  const redis = new Redis(redisUrl, {
    commandTimeout: timeoutMs,   // timeout: never wait long on the limiter
    maxRetriesPerRequest: 1,     // at most one quick retry, then give up
    enableOfflineQueue: false,   // fail fast when Redis is down, do not queue
  });
  redis.on('error', () => {});   // errors are handled per call below
  redis.defineCommand('tokenBucket', { numberOfKeys: 1, lua: TOKEN_BUCKET_LUA });

  // Returns { allowed, remaining, retryAfterSec, failedOpen }
  async function take(clientKey, cost = 1) {
    try {
      const [allowed, tokensStr] = await redis.tokenBucket(
        `rl:{${clientKey}}`, capacity, refillPerSec, cost);
      const tokens = parseFloat(tokensStr);
      return {
        allowed: allowed === 1,
        remaining: Math.floor(tokens),
        retryAfterSec: allowed === 1 ? 0 : Math.ceil((cost - tokens) / refillPerSec),
        failedOpen: false,
      };
    } catch (err) {
      // Fail open: availability of the API matters more than exact limits here.
      return { allowed: true, remaining: capacity, retryAfterSec: 0, failedOpen: true };
    }
  }

  return { take, capacity };
}

module.exports = { createRateLimiter };

const express = require('express');
const client = require('prom-client');
const { createRateLimiter } = require('./rateLimiter');

const PORT = Number(process.env.PORT || 3000);
const INSTANCE = process.env.INSTANCE || 'local';
const limiter = createRateLimiter({
  redisUrl: process.env.REDIS_URL || 'redis://localhost:6379',
  capacity: Number(process.env.RL_CAPACITY || 10),
  refillPerSec: Number(process.env.RL_REFILL_PER_SEC || 5),
  timeoutMs: Number(process.env.RL_REDIS_TIMEOUT_MS || 50),
});

// Metrics = the raw data for our SLIs.
const requests = new client.Counter({ name: 'http_requests_total', help: 'Requests', labelNames: ['route', 'code'] });
const latency = new client.Histogram({ name: 'http_request_duration_seconds', help: 'Latency',
  labelNames: ['route'], buckets: [0.01, 0.05, 0.1, 0.3, 0.5, 1, 2] });
const decisions = new client.Counter({ name: 'rate_limiter_decisions_total', help: 'Limiter results', labelNames: ['result'] });
const limiterErrors = new client.Counter({ name: 'rate_limiter_errors_total', help: 'Redis failures (failed open)' });
client.collectDefaultMetrics();

const app = express();

// Record every API request once it finishes (route + status code).
app.use('/v1', (req, res, next) => {
  const end = latency.startTimer({ route: req.path });
  res.on('finish', () => { end(); requests.inc({ route: req.path, code: String(res.statusCode) }); });
  next();
});

// Rate-limit middleware: key by API key, else by client IP.
app.use('/v1', async (req, res, next) => {
  const key = req.get('x-api-key') || `ip:${req.ip}`;
  const r = await limiter.take(key);
  if (r.failedOpen) limiterErrors.inc();
  decisions.inc({ result: r.allowed ? 'allowed' : 'limited' });
  res.set('RateLimit-Limit', String(limiter.capacity));
  res.set('RateLimit-Remaining', String(Math.max(0, r.remaining)));
  if (!r.allowed) {
    res.set('Retry-After', String(r.retryAfterSec)); // client should back off with jitter
    return res.status(429).json({ error: 'rate_limited', retryAfterSec: r.retryAfterSec });
  }
  next();
});

app.get('/v1/hello', (req, res) => res.json({ message: 'hello', servedBy: INSTANCE }));

// Health and metrics are not rate limited.
app.get('/healthz', (req, res) => res.send('ok'));
app.get('/metrics', async (req, res) => {
  res.set('Content-Type', client.register.contentType);
  res.send(await client.register.metrics());
});

app.listen(PORT, () => console.log(`${INSTANCE} listening on ${PORT}`));

