"""Consistent hashing with virtual nodes, plus an N/W/R quorum check.
Run it: python -m app.hashring
"""
import bisect
import hashlib
from collections import Counter


def _h(s: str) -> int:
    return int(hashlib.md5(s.encode()).hexdigest(), 16)  # fine for placement; not for security


class HashRing:
    def __init__(self, nodes: list[str], vnodes: int = 100):
        self.vnodes = vnodes  # many points per node gives an even spread
        self.ring: list[tuple[int, str]] = []
        for n in nodes:
            self.add(n)

    def add(self, node: str) -> None:
        for i in range(self.vnodes):
            bisect.insort(self.ring, (_h(f"{node}#{i}"), node))

    def preference_list(self, key: str, n: int) -> list[str]:
        """Walk clockwise from the key and collect n DISTINCT nodes (the replicas)."""
        i = bisect.bisect(self.ring, (_h(key), ""))
        out: list[str] = []
        while len(out) < n:
            node = self.ring[i % len(self.ring)][1]
            if node not in out:
                out.append(node)
            i += 1
        return out


def quorum(n: int, w: int, r: int) -> str:
    # W + R > N means every read set overlaps the latest write set
    return "strong (read sees latest write)" if w + r > n else "eventual (stale reads possible)"


if __name__ == "__main__":
    keys = [f"user:{i}" for i in range(10_000)]
    ring = HashRing(["cache-a", "cache-b", "cache-c"])
    before = {k: ring.preference_list(k, 1)[0] for k in keys}
    print("load per node:", Counter(before.values()))

    ring.add("cache-d")  # scale out by one node
    moved = sum(before[k] != ring.preference_list(k, 1)[0] for k in keys)
    print(f"keys moved after adding cache-d: {moved / len(keys):.0%} (ideal ~25%; mod-N would move ~75%)")

    print("replicas for user:42 ->", ring.preference_list("user:42", 3))
    for n, w, r in [(3, 2, 2), (3, 1, 1), (3, 3, 1)]:
        print(f"N={n} W={w} R={r}: {quorum(n, w, r)}")

